def get_model_list():
    base_dir = os.getcwd()
    model_dir = os.path.join(base_dir, "resources", "llm_model")
    models = []
    if os.path.exists(model_dir):
        for f in os.listdir(model_dir):
            if f.endswith(".gguf"):
                models.append(f)
    return models

class LlamaServerManager:
    def __init__(self):
        self.process = None
        self.current_model_path = None
        self.port = 8080

    def cleanup(self, signum=None, frame=None):
        if self.process:
            print(f"正在关闭翻译服务... (PID: {self.process.pid})")
            try:
                parent = psutil.Process(self.process.pid)
                for child in parent.children(recursive=True):
                    child.terminate()
                parent.terminate()
                print("翻译服务已终止")
            except psutil.NoSuchProcess:
                pass
            except Exception as e:
                print(f"关闭翻译服务时出错: {e}")
            finally:
                self.process = None
                self.current_model_path = None

    def start_server_and_get_url(self, model_name=None):
        # 路径定义 (基于当前工作目录)
        base_dir = os.getcwd()
        server_exe = os.path.join(base_dir, "resources", "llamacpp", "llama-server.exe")
        
        # 搜索模型文件
        model_dir = os.path.join(base_dir, "resources", "llm_model")
        
        target_model_path = None
        if model_name:
             possible_path = os.path.join(model_dir, model_name)
             if os.path.exists(possible_path):
                 target_model_path = possible_path

        if not target_model_path and os.path.exists(model_dir):
            for f in os.listdir(model_dir):
                if f.endswith(".gguf"):
                    target_model_path = os.path.join(model_dir, f)
                    break
        
        if not os.path.exists(server_exe):
            print(f"[自启动跳过] 未找到 llama-server.exe: {server_exe}")
            return None, "http://127.0.0.1:8080"
            
        if not target_model_path:
            print(f"[自启动跳过] 在 {model_dir} 中未找到 .gguf 模型文件。")
            return None, "http://127.0.0.1:8080"
            
        # Check if already running with same model
        if self.process and self.process.poll() is None and self.current_model_path == target_model_path:
             return self.process, f"http://127.0.0.1:{self.port}"
             
        # If running (w/ diff model or dead), cleanup
        if self.process:
            self.cleanup()

        # 寻找可用端口
        target_port = 8080
        for p in range(8080, 8101):
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                if s.connect_ex(('127.0.0.1', p)) != 0:
                    target_port = p
                    break
        else:
            print("警告: 8080-8100 端口均被占用，将尝试使用 8080 (可能会冲突)")
            target_port = 8080

        cmd = [
            server_exe,
            "-m", target_model_path,
            "--port", str(target_port),
            "--host", "127.0.0.1",
            "--ctx-size", "8192",
            "--n-gpu-layers", "100"
        ]

        print(f"正在后台启动本地翻译服务...\n命令: {' '.join(cmd)}")
        try:
            # CREATE_NO_WINDOW = 0x08000000 (Windows only)
            creation_flags = 0x08000000 if os.name == 'nt' else 0
            process = subprocess.Popen(
                cmd,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=creation_flags
            )
            print(f"翻译服务启动成功 (PID: {process.pid}, Port: {target_port})")
            self.process = process
            self.current_model_path = target_model_path
            self.port = target_port
            return process, f"http://127.0.0.1:{target_port}"
        except Exception as e:
            print(f"无法启动翻译服务: {e}")
            return None, "http://127.0.0.1:8080"

llama_manager = LlamaServerManager()

