def console_ctrl_handler(ctrl_type):
    llama_manager.cleanup()
    return False

if sys.platform == "win32":
    kernel32 = ctypes.WinDLL("kernel32")
    handler_func = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_uint)(console_ctrl_handler)
    kernel32.SetConsoleCtrlHandler(handler_func, True)

atexit.register(llama_manager.cleanup)
signal.signal(signal.SIGINT, llama_manager.cleanup)
signal.signal(signal.SIGTERM, llama_manager.cleanup)

