async def parse_pdf(doc_path, output_dir, end_page_id, is_ocr, formula_enable, table_enable, language, backend, url):
    os.makedirs(output_dir, exist_ok=True)

    try:
        file_name = f'{safe_stem(Path(doc_path).stem)}_{time.strftime("%y%m%d_%H%M%S")}'
        pdf_data = await asyncio.to_thread(read_fn, doc_path)
        if is_ocr:
            parse_method = 'ocr'
        else:
            parse_method = 'auto'

        if backend.startswith("vlm"):
            parse_method = "vlm"

        local_image_dir, local_md_dir = await asyncio.to_thread(prepare_env, output_dir, file_name, parse_method)
        await aio_do_parse(
            output_dir=output_dir,
            pdf_file_names=[file_name],
            pdf_bytes_list=[pdf_data],
            p_lang_list=[language],
            parse_method=parse_method,
            end_page_id=end_page_id,
            formula_enable=formula_enable,
            table_enable=table_enable,
            backend=backend,
            server_url=url,
        )
        return local_md_dir, file_name
    except Exception as e:
        logger.exception(e)
        return None, None


def compress_directory_to_zip(directory_path, output_zip_path, keep_files=None):
    """压缩指定目录到一个 ZIP 文件。

    :param directory_path: 要压缩的目录路径
    :param output_zip_path: 输出的 ZIP 文件路径
    :param keep_files: 要保留的文件类型列表，None表示保留所有文件
    """
    try:
        with zipfile.ZipFile(output_zip_path, 'w', zipfile.ZIP_DEFLATED) as zipf:

            # 遍历目录中的所有文件和子目录
            for root, dirs, files in os.walk(directory_path):
                for file in files:
                    # 构建完整的文件路径
                    file_path = os.path.join(root, file)
                    # 计算相对路径
                    arcname = os.path.relpath(file_path, directory_path)
                    
                    # 检查是否需要保留该文件
                    if keep_files is None:
                        # 保留所有文件
                        zipf.write(file_path, arcname)
                    else:
                        # 只保留指定类型的文件
                        file_ext = os.path.splitext(file)[1].lower()
                        if file_ext in keep_files:
                            zipf.write(file_path, arcname)
                        # 特殊处理：保留图片文件夹中的所有文件
                        elif 'images' in root.lower() or 'image' in root.lower():
                            zipf.write(file_path, arcname)
        return 0
    except Exception as e:
        logger.exception(e)
        return -1





async def parse_office(doc_path, output_dir):
    os.makedirs(output_dir, exist_ok=True)
    file_name = f'{safe_stem(Path(doc_path).stem)}_{time.strftime("%y%m%d_%H%M%S")}'
    local_md_dir = os.path.join(output_dir, file_name)
    os.makedirs(local_md_dir, exist_ok=True)
    
    output_path = os.path.join(local_md_dir, f"{file_name}.md")
    
    cmd = [
        sys.executable, "-m", "markitdown",
        doc_path,
        "-o", output_path,
        "--keep-data-uris"
    ]
    
    creation_flags = 0x08000000 if os.name == 'nt' else 0
    
    def run_cmd():
        return subprocess.run(cmd, capture_output=True, text=True, encoding='utf-8', errors='replace', creationflags=creation_flags)

    try:
        result = await asyncio.to_thread(run_cmd)
        if result.returncode != 0:
            logger.error(f"MarkItDown conversion failed for {doc_path}: {result.stderr}")
            return None, None
    except Exception as e:
        logger.exception(f"Exception during MarkItDown conversion: {e}")
        return None, None
        
    return local_md_dir, file_name


async def to_markdown(file_path, end_pages=10, is_ocr=False, formula_enable=False, table_enable=True, language="ch", backend="pipeline", url=None, to_word=True, to_excel=False, to_html=False, translate_enable=False, translate_url="http://127.0.0.1:8080"):
    ext = os.path.splitext(file_path)[1].lower()
    if ext in ['.docx', '.xlsx', '.pptx']:
        local_md_dir, file_name = await parse_office(file_path, './output')
    else:
        file_path = await asyncio.to_thread(to_pdf, file_path)
        # 获取识别的md文件以及压缩包文件路径
        local_md_dir, file_name = await parse_pdf(file_path, './output', end_pages - 1, is_ocr, formula_enable, table_enable, language, backend, url)
    
    if local_md_dir is None:
        logger.error(f'解析失败: {file_path}')
        return None, None, None, None
        
    archive_zip_path = os.path.join('./output', str_sha256(local_md_dir) + '.zip')
    md_path = os.path.join(local_md_dir, file_name + '.md')

    if translate_enable:
        logger.info(f'开始翻译: {file_name} -> URL: {translate_url}')
        try:
            success = await asyncio.to_thread(translate_markdown_file, md_path, md_path, translate_url)
            if success:
                logger.info('翻译成功')
            else:
                logger.error('翻译失败')
        except Exception as e:
            logger.error(f'翻译异常: {e}')

    
    docx_path = None
    if to_word:
        docx_path = await asyncio.to_thread(convert_markdown_to_word, md_path)

    xlsx_path = None
    if to_excel:
        # 将MD转换为Excel
        xlsx_path = os.path.join(local_md_dir, file_name + '.xlsx')
        try:
            await asyncio.to_thread(convert_markdown_to_excel, md_path, xlsx_path)
            logger.info('Excel转换成功')
        except Exception as e:
            logger.error(f'Excel转换失败: {e}')
    
    html_path = None
    if to_html:
        # 将MD转换为HTML
        html_path = os.path.join(local_md_dir, file_name + '.html')
        try:
            await asyncio.to_thread(convert_markdown_to_html, md_path, html_path)
            logger.info('HTML转换成功')
        except Exception as e:
            logger.error(f'HTML转换失败: {e}')

    # 设置要保留的文件类型
    keep_files = ['.md']
    if to_word:
        keep_files.append('.docx')
    if to_excel:
        keep_files.append('.xlsx')
    if to_html:
        keep_files.append('.html')
    zip_archive_success = await asyncio.to_thread(compress_directory_to_zip, local_md_dir, archive_zip_path, keep_files)
    if zip_archive_success == 0:
        logger.info('压缩成功')
    else:
        logger.error('压缩失败')
    
    return local_md_dir, file_name, archive_zip_path, docx_path


async def batch_to_markdown(file_paths, end_pages=10, is_ocr=False, formula_enable=False, table_enable=True, language="ch", backend="pipeline", url=None, to_word=True, to_excel=False, to_html=False, translate_enable=False, translate_url="http://127.0.0.1:8080"):
    # 处理多个文件，每个文件对应一个文件夹
    all_results = []
    for file_path in file_paths:
        result = await to_markdown(file_path, end_pages, is_ocr, formula_enable, table_enable, language, backend, url, to_word, to_excel, to_html, translate_enable, translate_url)
        if result[0] is not None:
             local_md_dir, file_name, _, _ = result
             all_results.append((local_md_dir, file_name))
    
    # 创建一个临时目录来存放所有生成的文件夹
    batch_output_dir = os.path.join('./output', f'batch_{time.strftime("%y%m%d_%H%M%S")}')
    os.makedirs(batch_output_dir, exist_ok=True)
    
    # 将每个生成的文件夹复制到临时目录中，使用file_name作为子目录名
    for md_dir, file_name in all_results:
        import shutil
        # 使用file_name作为子目录名，确保唯一性
        target_dir = os.path.join(batch_output_dir, file_name)
        await asyncio.to_thread(shutil.copytree, md_dir, target_dir)
    
    # 压缩整个临时目录
    batch_zip_path = os.path.join('./output', f'batch_{time.strftime("%y%m%d_%H%M%S")}.zip')
    # 设置要保留的文件类型
    keep_files = ['.md']
    if to_word:
        keep_files.append('.docx')
    if to_excel:
        keep_files.append('.xlsx')
    if to_html:
        keep_files.append('.html')
    zip_archive_success = await asyncio.to_thread(compress_directory_to_zip, batch_output_dir, batch_zip_path, keep_files)
    if zip_archive_success == 0:
        logger.info('批量压缩成功')
    else:
        logger.error('批量压缩失败')
    
    # 返回批量压缩包路径，docx_path返回None
    return batch_zip_path, None


